    "    S.wire(\"D\", \"ff.a\");",
    "    S.wire(\"CLK\", \"ff.b\");",
    "    S.pin(\"Q\", 4.6, 1.0, \"right\");",
    "    S.wire(\"ff\", \"Q\");",
    "    return S;",
    "}",
    "",
    "int main() {",
    "    Schematic sch = dff();",
    "",
    "    {",
    "        std::vector<int> D(N, 0), CLK(N, 0);",
